import math

def is_power_of_five(N):
    """Checks if N is a power of 5 (N = 5^k for some non-negative integer k)."""
    if N <= 0:
        return False
    if N == 1:
        return True # 5^0 = 1

    # Repeatedly divide by 5
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

# Check odd integers n from 21 up to 50 (inclusive of 21, exclusive of 51)
start_n = 21
end_n = 51 # range stops before this value
solutions = []

print(f"Starting check for odd n from {start_n} to {end_n-1}...")

for n in range(start_n, end_n, 2):
    N = (2**n) - 3

    if is_power_of_five(N):
        # Determine k: k = log5(N)
        # Since N is guaranteed to be a power of 5 if we reach here, we can calculate k
        try:
            k = round(math.log(N, 5))
            # Basic sanity check, though usually unnecessary if is_power_of_five is correct
            if 5**k == N:
                 solutions.append((n, k))
        except ValueError:
            # Should not happen for N > 0
            pass

if solutions:
