def check_order(a, m):
    for k in range(1, m + 1):
        if pow(a, k, m) == 1:
            return k
    return -1

def find_exponent(base, target, modulus):
    for n in range(1, modulus + 1):
        if pow(base, n, modulus) == target:
            return n
    return None

